// Builds + sends a backup document to the admin chat. kind "backup" is a
// manual download (audited); kind "pre-restore" is the automatic safety
// copy sent right before a restore is applied. THROWS when Telegram
// refuses the document — the restore flow treats that as an abort signal.
// (Captions are plain text: tgUploadDocument sends no parse_mode.)
export async function sendBackupDocument(env, chatId, kind = "backup") {
  const { backup, bytes, filename, counts } = await buildBackupFile(env, kind);
  const caption = kind === "pre-restore"
    ? `🛟 بکاپ ایمنی قبل از ریستور\n📅 ${tehranDateText(backup.createdAt)}\n${backupCountsLine(counts)}\n\nاین فایل، وضعیت فروشگاه درست قبل از ریستور است؛ اگر نتیجه ریستور را نخواستید، همین فایل را دوباره ریستور کنید.\n\n⚠️ این فایل شامل تنظیمات فروشگاه (از جمله اطلاعات کارت و کلید اتراسکن) است؛ آن را امن نگه دارید.`
    : `💾 بکاپ فروشگاه BlueMajazi\n📅 ${tehranDateText(backup.createdAt)}\n${backupCountsLine(counts)}\n\n⚠️ این فایل را مثل رمز عبور نگه دارید: شامل تنظیمات فروشگاه است — از جمله اطلاعات کارت بانکی، آدرس کیف‌پول‌ها و کلید API اتراسکن. برای کسی نفرستید و جای امنی نگهش دارید. (کلید SmsFull در بکاپ نیست؛ آن سکرت کلودفلر است.)\n\nدر بکاپ نیست: پرداخت‌ها (topup)، نشست‌های وب، قفل‌ها، کش نرخ و سوابق تغییرات.`;
  await tgUploadDocument(env, chatId, bytes, filename, caption, "application/json");
  if (kind === "backup") {
    await logAudit(env, { actor: chatId, action: "backup_dl", extra: backupCountsLine(counts) });
  }
  return { backup, counts, filename };
}

// The admin sent a document while in the restore-upload state: download
// it from Telegram, validate it strictly, and — only when valid — stash
// it (10 minutes) and ask for an explicit confirmation. NOTHING from the
// backup is written here.
export async function handleRestoreUpload(env, msg, user) {
  const chatId = msg.chat.id;
  const doc = msg.document || {};
  if (doc.file_size && doc.file_size > MAX_BACKUP_BYTES) {
    return send(env, chatId, "❌ فایل بکاپ بزرگ‌تر از ۵ مگابایت است و قبول نمی‌شود. فایل درست را بفرستید یا /cancel بزنید.");
  }
  let parsed = null;
  try {
    const gf = await tg(env, "getFile", { file_id: doc.file_id });
    const path = gf?.result?.file_path;
    if (!path) throw new Error("getFile failed");
    const res = await fetch(`https://api.telegram.org/file/bot${env.TELEGRAM_BOT_TOKEN}/${path}`);
    if (!res.ok) throw new Error("file download failed");
    const buf = await res.arrayBuffer();
    if (buf.byteLength > MAX_BACKUP_BYTES) throw new Error("backup file too large");
    parsed = JSON.parse(new TextDecoder().decode(buf));
  } catch (e) {
    return send(env, chatId, "❌ خواندن فایل بکاپ ناموفق بود (فایل از تلگرام دانلود یا خوانده نشد). دوباره بفرستید یا /cancel بزنید.");
  }
  const v = validateBackup(parsed);
  if (!v.ok) {
    return send(env, chatId, `❌ <b>بکاپ قبول نشد:</b> ${esc(v.error)}\n\nهیچ تغییری اعمال نشد. فایل درست را بفرستید یا /cancel بزنید.`);
  }
  user.state = null; await saveUser(env, user);
  await kvPut(env, `restore:${chatId}`, { backup: parsed, at: now() }, 600);
  const c = backupCounts(parsed);
  const text = `⬆️ <b>تأیید ریستور بکاپ</b>\n\n📅 تاریخ بکاپ: <b>${esc(tehranDateText(parsed.createdAt))}</b>\n🤖 نسخه ربات موقع ساخت بکاپ: ${esc(faDigits(String(parsed.botVersion || "؟")))}\n${backupCountsLine(c)}\n\n⚠️ <b>هشدار:</b> تنظیمات، پکیج‌ها، کوپن‌ها، کاربران و سفارش‌های <b>فعلی</b> به‌طور کامل با این بکاپ <b>جایگزین</b> می‌شوند (ادغام نمی‌شوند).\n\nقبل از اعمال، یک بکاپ از وضعیت فعلی به‌صورت خودکار برایتان ارسال می‌شود؛ اگر ارسال آن ناموفق باشد، ریستور انجام نمی‌شود.\n\nاین تأیید تا ۱۰ دقیقه معتبر است.`;
  return send(env, chatId, text, kb([
    [btn("✅ تأیید ریستور", "rstok"), btn("❌ لغو", "rstcancel")],
  ]));
}

